-- content_ir_quiz_trust_envelope.sql
-- Registry correction (2026-08-25, feedback 499a460f): the quiz kinds carry
-- the per-question grounding the live Assessment Quiz agents already emit
-- (trust / depth / topic / rubric / acceptable_answers / points), plus a
-- nullable correct_answer for written_response items — the same correction
-- flashcard_set got on 2026-08-22. `ai.agent.produce` binds the KIND schema
-- above the agent's own, so the missing fields were silently deleted on every
-- kind-bound run (live proof: study_pack_v2 run 46c935e8, 10 questions, zero
-- trust keys). Re-emitted through the ONE sanctioned emitter
-- (scripts/shape/emit-kind-rows.ts). Idempotent; strictly additive
-- (every legacy field keeps its exact live type and requiredness, except
-- correct_answer/description which only WIDEN to nullable).
begin;

update content_ir.kind_definition set
  data = '[{"name":"title","required":true,"type":"string"},{"name":"description","nullable":true,"type":"string"},{"name":"questions","required":true,"type":"array"},{"name":"additionalDetails","type":"inline_object","fields":[],"open":true}]'::jsonb,
  emitted_block_schema = '{"type":"object","properties":{"title":{"type":"string"},"description":{"type":["string","null"]},"questions":{"type":"array","items":{"$ref":"#/$defs/quiz_question"}},"additionalDetails":{"type":"object","properties":{},"required":[],"additionalProperties":true},"__kind":{"type":"string","description":"Block discriminator for render pipeline.","const":"quiz_set"}},"required":["__kind","title","questions"],"additionalProperties":false,"$defs":{"quiz_question":{"type":"object","properties":{"type":{"type":"string"},"question":{"type":"string"},"options":{"type":"array","items":{"type":"string"}},"correct_answer":{"type":["string","null"]},"explanation":{"type":"string"},"acceptable_answers":{"type":["array","null"],"items":{"type":"string"}},"rubric":{"type":["string","null"]},"depth":{"type":"string"},"topic":{"type":["string","null"]},"points":{"type":"number"},"trust":{"$ref":"#/$defs/trust_envelope"},"additionalDetails":{"type":"object","properties":{},"required":[],"additionalProperties":true},"__kind":{"type":"string","description":"Block discriminator for render pipeline.","const":"quiz_question"}},"required":["__kind","type","question","correct_answer"],"additionalProperties":false},"trust_envelope":{"type":"object","properties":{"confidence":{"type":"string","enum":["grounded","inferred","not_in_material"],"description":"How well the claim is supported by the provided material."},"groundedIn":{"type":["string","null"],"description":"Human-readable description of the material the answer is grounded in."},"citations":{"type":"array","items":{"$ref":"#/$defs/citation"},"description":"Supporting citations."},"__kind":{"type":"string","description":"Block discriminator for render pipeline.","const":"trust_envelope"}},"required":["__kind","confidence"],"additionalProperties":false},"citation":{"type":"object","properties":{"sourceId":{"type":"string","description":"Stable identifier of the cited source."},"sourceKind":{"type":"string","en