  emitted_json_schema = '{"type":"object","properties":{"title":{"type":"string"},"description":{"type":["string","null"]},"questions":{"type":"array","items":{"$ref":"#/$defs/quiz_question"}},"additionalDetails":{"type":"object","properties":{},"required":[],"additionalProperties":true},"__kind":{"type":"string","description":"Block discriminator for render pipeline.","const":"quiz_set"}},"required":["__kind","title","questions"],"additionalProperties":false,"$defs":{"quiz_question":{"type":"object","properties":{"type":{"type":"string"},"question":{"type":"string"},"options":{"type":"array","items":{"type":"string"}},"correct_answer":{"type":["string","null"]},"explanation":{"type":"string"},"acceptable_answers":{"type":["array","null"],"items":{"type":"string"}},"rubric":{"type":["string","null"]},"depth":{"type":"string"},"topic":{"type":["string","null"]},"points":{"type":"number"},"trust":{"$ref":"#/$defs/trust_envelope"},"additionalDetails":{"type":"object","properties":{},"required":[],"additionalProperties":true},"__kind":{"type":"string","description":"Block discriminator for render pipeline.","const":"quiz_question"}},"required":["__kind","type","question","correct_answer"],"additionalProperties":false},"trust_envelope":{"type":"object","properties":{"confidence":{"type":"string","enum":["grounded","inferred","not_in_material"],"description":"How well the claim is supported by the provided material."},"groundedIn":{"type":["string","null"],"description":"Human-readable description of the material the answer is grounded in."},"citations":{"type":"array","items":{"$ref":"#/$defs/citation"},"description":"Supporting citations."},"__kind":{"type":"string","description":"Block discriminator for render pipeline.","const":"trust_envelope"}},"required":["__kind","confidence"],"additionalProperties":false},"citation":{"type":"object","properties":{"sourceId":{"type":"string","description":"Stable identifier of the cited source."},"sourceKind":{"type":"string","enu